    category: '省エネ・制御・設備計画',
    question: '空調自動制御に関する記述のうち、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: 'PID制御は、比例（P）・積分（I）・微分（D）の各動作を組み合わせたフィードバック制御方式である。', explanation: '適当。PID制御は偏差に応じた比例動作、蓄積偏差に応じた積分動作、変化速度に応じた微分動作を組み合わせる代表的な制御方式である。' },
      { key: 'B', text: '積分動作（I動作）は、偏差の時間積分に応じて操作量を変化させ、比例制御で生じるオフセットを解消する働きがある。', explanation: '適当。積分動作は偏差が残る限り操作量を増減させ続けるため、定常偏差（オフセット）を解消できる。' },
      { key: 'C', text: '外気冷房（エコノマイザ）制御は、外気条件が室内よりも冷房に有利な場合に、外気を積極的に導入して冷房負荷を低減する制御である。', explanation: '適当。中間期等、外気エンタルピーが室内より低い場合に外気を多く取り入れることで、冷凍機負荷を低減できる制御である。' },
      { key: 'D', text: '外気冷房制御は、外気条件にかかわらず常に外気導入量を最小に絞ることで省エネルギーを図る制御方式である。', explanation: '不適当。外気冷房は外気条件が冷房に有利な場合（外気エンタルピーが室内より低い場合等）に、むしろ外気導入量を「増やす」ことで冷凍機負荷を低減する制御方式であり、「常に外気を最小に絞る」というのは趣旨が逆である。' },
    ],
    correctKey: 'D',
    explanation: 'P動作はオフセットが残る。I動作でオフセット解消。外気冷房は有利な条件で外気を増やす制御。\n【図解】\n　自動制御の要点\n　P動作：偏差比例、オフセットが残る★\n　I動作：オフセット解消★\n　D動作：変化速度に応じた制御\n　外気冷房：条件が良ければ外気導入を増やす★（常に絞るのは誤り）',
