    category: '熱環境・熱負荷',
    question: '結露防止に関する記述のうち、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: '表面結露は、室内側表面温度が室内空気の露点温度を上回った場合に発生する現象である。', explanation: '不適当。表面結露は表面温度が室内空気の露点温度「以下」になったときに水蒸気が凝縮して生じる現象であり、「露点温度を上回った場合に発生する」というのは条件が逆である。' },
      { key: 'B', text: '内部結露は、壁体内部の温度分布と水蒸気分圧分布の関係により、壁体内部で結露が生じる現象である。', explanation: '適当。壁体内部を通過する水蒸気が、内部の露点温度以下となる位置で凝縮し内部結露が生じる。' },
      { key: 'C', text: '断熱性能を高め、室内側表面温度を露点温度より高く保つことは、表面結露防止に有効である。', explanation: '適当。断熱により表面温度低下を抑制できれば、室内空気の露点温度を下回りにくくなり結露を防止できる。' },
      { key: 'D', text: '防湿層（防湿層フィルム等）を断熱材の室内側に設けることは、内部結露防止の対策として用いられる。', explanation: '適当。室内側からの水蒸気の壁体内部への侵入を防湿層で抑制することで、内部結露のリスクを低減できる。' },
    ],
    correctKey: 'A',
