    category: '省エネ・制御・設備計画',
    question: '蓄熱システムに関する記述のうち、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: '氷蓄熱システムは、水蓄熱システムに比べて同じ蓄熱量を得るための蓄熱槽容積が大きくなる。', explanation: '不適当。氷は水に比べて単位体積あたりの蓄熱量（融解潜熱を利用できる分）が大きいため、同じ蓄熱量を得る場合、一般に氷蓄熱の方が水蓄熱より蓄熱槽容積を小さくできる。記述は関係が逆である。' },
      { key: 'B', text: '水蓄熱システムは、水の顕熱を利用して冷熱・温熱を蓄える方式で、氷蓄熱に比べ蓄熱槽容積が大きくなる傾向がある。', explanation: '適当。水は氷に比べ単位体積あたりの蓄熱量（潜熱を利用しない分）が小さいため、同じ蓄熱量では槽容積が大きくなりやすい。' },
      { key: 'C', text: '蓄熱システムの導入により、熱源機器の容量を負荷のピーク値そのものではなく、平準化された熱量を基準に選定できる場合がある。', explanation: '適当。蓄熱により熱源の運転を負荷平準化できるため、ピーク対応の過大な熱源容量を避けられる場合がある。' },
      { key: 'D', text: '蓄熱槽の運用には、蓄熱量の管理や槽内の温度成層（温度分布）を維持するための運転制御が重要である。', explanation: '適当。効率的な蓄熱・放熱のためには、槽内での温度成層を崩さないような配管・制御計画が重要である。' },
    ],
